function numSamples(sr, dur){ return sr*dur; }
function pcmBytes(sr, dur, channels, bits){ return Math.round(sr*dur*channels*(bits/8)); }
function humanSize(bytes){ var u=['B','KB','MB','GB']; var i=0, b=bytes; while(b>=1024&&i<u.length-1){b/=1024;i++;} return b.toFixed(2)+' '+u[i]; }
var COMMON=[8000,16000,22050,44100,48000,96000,192000];
var EXPORTS={ numSamples:numSamples, pcmBytes:pcmBytes, humanSize:humanSize, COMMON:COMMON };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.SampleForgePure = EXPORTS; }
